-- Remise en vente, sous leur vrai nom, des 1 566 fiches qui ne sont pas des
-- packs d'ampoules (8 novembre 2026).
--
-- Retirées par 20261108160000 parce qu'elles s'annonçaient comme des ampoules
-- « sans modifier le câblage ». L'exploitant veut « le même catalogue que
-- LedPerf » : elles reviennent pour ce qu'elles sont — feux LED antibrouillard
-- et longue portée, phares additionnels, optiques, boîtier de phare rond,
-- centrale de clignotants, clignotants séquentiels, clignotants de
-- rétroviseurs, répétiteurs latéraux. Le type se lit ensuite dans le nom
-- (src/lib/types-produit.ts) : photo du produit, description Google, réponse
-- sur le câblage.
--
-- Pour chaque fiche : nom, accroche, description, texte et nom du
-- conditionnement réécrits (le véhicule est relu dans le nom actuel, déjà
-- nettoyé de « (photo manquante...) ») ; emplacement AUX (feux additionnels)
-- ou TURN_RELAY (centrale) ; rubrique « Phares additionnels » ou « Décodeurs
-- anti-erreur » ; statut PUBLISHED. Les adresses ne changent pas.

INSERT INTO "LightPosition" ("id", "code", "label", "family", "defaultQty", "position")
VALUES
  ('lp_aux', 'AUX', 'Feux additionnels', 'HEADLIGHT', 2, 11),
  ('lp_turn_relay', 'TURN_RELAY', 'Centrale de clignotants', 'TURN_SIGNAL', 1, 12)
ON CONFLICT ("code") DO NOTHING;

