UPDATE "Product" p
SET
  "name" = 'Feux LED antibrouillard et longue portée pour ' || c.vehicule,
  "tagline" = 'Pour les feux additionnels de votre ' || c.vehicule,
  "description" = 'Feux LED antibrouillard et longue portée pour ' || c.vehicule || '. ' || 'Deux feux LED antibrouillard et longue portée, livrés avec faisceau (relais et fusible), interrupteur de guidon et fixations.',
  "body" = replace('Deux feux LED à ajouter à l’avant de votre {v} : dans le même feu, un faisceau large et proche pour le brouillard, et un faisceau qui porte loin.', '{v}', vehicule) || E'\n\n' || replace('Ils viennent **en plus des phares d’origine**, qui restent en place. Ils se fixent sur un tube à l’avant de la moto (crash bar, protection moteur ou guidon, selon le modèle) et se branchent avec le faisceau fourni. Réglez-les vers le bas pour ne pas éblouir les véhicules en face.', '{v}', vehicule) || E'\n\n' || replace('## Dans le carton

- 2 feux LED, boîtier aluminium étanche
- 1 faisceau électrique avec relais et fusible
- 1 interrupteur à fixer au guidon
- Les pattes et colliers de fixation', '{v}', vehicule) || E'\n\n' || replace('## Avant de commander

Vérifiez qu’un tube est libre à l’avant de votre {v} pour fixer les feux. En cas de doute, envoyez-nous une photo de l’avant de la moto : nous vous disons où les monter.', '{v}', vehicule) || E'\n',
  "metaTitle" = NULL,
  "metaDescription" = NULL,
  "status" = 'PUBLISHED',
  "publishedAt" = COALESCE(p."publishedAt", NOW()),
  "updatedAt" = NOW()
FROM cible c
WHERE p."id" = c."id" AND c.vehicule IS NOT NULL;

