UPDATE "Product" p
SET
  "name" = 'Phares additionnels LED pour ' || c.vehicule,
  "tagline" = 'Pour les phares additionnels de votre ' || c.vehicule,
  "description" = 'Phares additionnels LED pour ' || c.vehicule || '. ' || 'Deux phares LED ronds additionnels, livrés avec faisceau (relais et fusible), interrupteur et fixations.',
  "body" = replace('Deux petits phares LED ronds à ajouter à l’avant de votre {v}, pour voir plus loin la nuit.', '{v}', vehicule) || E'\n\n' || replace('Ils viennent **en plus des phares d’origine**, qui restent en place. Ils se fixent à l’avant du véhicule avec les pattes fournies et se branchent avec le faisceau livré. Réglez-les vers le bas pour ne pas éblouir les véhicules en face.', '{v}', vehicule) || E'\n\n' || replace('## Dans le carton

- 2 phares LED ronds, boîtier aluminium étanche
- 1 faisceau électrique avec relais et fusible
- 1 interrupteur
- Les pattes de fixation', '{v}', vehicule) || E'\n\n' || replace('## Avant de commander

Vérifiez qu’un emplacement est libre à l’avant de votre {v} pour les fixer. En cas de doute, envoyez-nous une photo : nous vous disons où les monter.', '{v}', vehicule) || E'\n',
  "metaTitle" = NULL,
  "metaDescription" = NULL,
  "status" = 'PUBLISHED',
  "publishedAt" = COALESCE(p."publishedAt", NOW()),
  "updatedAt" = NOW()
FROM cible c
WHERE p."id" = c."id" AND c.vehicule IS NOT NULL;

