-- optiques : 15 fiches -----------------------------------------------------
WITH cible AS (
  SELECT p."id", substring(p."name" from ' pour (.+)$') AS vehicule
  FROM "Product" p
  WHERE p."id" IN (SELECT DISTINCT v."productId" FROM "ProductVariant" v WHERE v."sku" IN (
    'LUM-PK-HEAD-HARLEY-DAVIDSON-DELUXE-1-D24B',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--4C52',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--993B',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--B2F4',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--F158',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-HERITAGE-AE35',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-HERITAGE-B511',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ROAD-KIN-0FA1',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ROAD-KIN-8494',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ROAD-KIN-D7C1',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ROAD-KIN-EEFC',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-SWITCHBA-6DFC',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-TRI-GLID-9C67',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-TRI-GLID-D2A7',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ULTRA-CL-5F80'
  ))
    AND p."name" LIKE 'Pack %'
)
UPDATE "Product" p
SET
  "name" = 'Optiques LED pour phares additionnels de ' || c.vehicule,
  "tagline" = 'Pour les phares additionnels de votre ' || c.vehicule,
  "description" = 'Optiques LED pour phares additionnels de ' || c.vehicule || '. ' || 'Des optiques LED à la place de celles des phares additionnels d’origine.',
  "body" = replace('Des optiques LED qui prennent la place de celles des phares additionnels montés d’origine sur votre {v}.', '{v}', vehicule) || E'\n\n' || replace('Les boîtiers d’origine restent en place : seules les optiques changent, pour une lumière blanche et plus puissante.', '{v}', vehicule) || E'\n\n' || replace('## Dans le carton

- Les optiques LED pour les phares additionnels', '{v}', vehicule) || E'\n\n' || replace('## Avant de commander

Ce produit est prévu pour les phares additionnels d’origine de votre {v}. En cas de doute sur votre version, écrivez-nous avec le modèle exact : nous vérifions.', '{v}', vehicule) || E'\n',
  "metaTitle" = NULL,
  "metaDescription" = NULL,
  "status" = 'PUBLISHED',
  "publishedAt" = COALESCE(p."publishedAt", NOW()),
  "updatedAt" = NOW()
FROM cible c
WHERE p."id" = c."id" AND c.vehicule IS NOT NULL;

UPDATE "ProductVariant" v
SET "name" = p."name", "updatedAt" = NOW()
FROM "Product" p
WHERE v."productId" = p."id"
  AND p."id" IN (SELECT DISTINCT v."productId" FROM "ProductVariant" v WHERE v."sku" IN (
    'LUM-PK-HEAD-HARLEY-DAVIDSON-DELUXE-1-D24B',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--4C52',
