  AND pc."productId" IN (SELECT DISTINCT v."productId" FROM "ProductVariant" v WHERE v."sku" IN (
    'LUM-PK-HEAD-HARLEY-DAVIDSON-DELUXE-1-D24B',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--4C52',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--993B',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--B2F4',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ELECTRA--F158',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-HERITAGE-AE35',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-HERITAGE-B511',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ROAD-KIN-0FA1',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ROAD-KIN-8494',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ROAD-KIN-D7C1',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ROAD-KIN-EEFC',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-SWITCHBA-6DFC',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-TRI-GLID-9C67',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-TRI-GLID-D2A7',
    'LUM-PK-HEAD-HARLEY-DAVIDSON-ULTRA-CL-5F80'
  ))
  AND EXISTS (
    SELECT 1 FROM "ProductCategory" pc2 JOIN "Category" c2 ON c2."id" = pc2."categoryId"
    WHERE pc2."productId" = pc."productId" AND c2."slug" = 'phares-additionnels'
  );

-- boitier : 13 fiches -----------------------------------------------------
WITH cible AS (
  SELECT p."id", substring(p."name" from ' pour (.+)$') AS vehicule
  FROM "Product" p
  WHERE p."id" IN (SELECT DISTINCT v."productId" FROM "ProductVariant" v WHERE v."sku" IN (
    'LUM-PK-HEAD-MOTO-GUZZI-AUDACE-1400-B2B7',
    'LUM-PK-HEAD-MOTO-GUZZI-BELLAGIO-940-9666',
    'LUM-PK-HEAD-MOTO-GUZZI-BREVA-1100-12-B6E4',
    'LUM-PK-HEAD-MOTO-GUZZI-BREVA-750-F9F3',
    'LUM-PK-HEAD-MOTO-GUZZI-CALIFORNIA-11-6C0B',
    'LUM-PK-HEAD-MOTO-GUZZI-CALIFORNIA-14-CB0F',
    'LUM-PK-HEAD-MOTO-GUZZI-GRISO-1100-3AE9',
    'LUM-PK-HEAD-MOTO-GUZZI-GRISO-1200-C95A',
    'LUM-PK-HEAD-MOTO-GUZZI-GRISO-850-15CF',
    'LUM-PK-HEAD-MOTO-GUZZI-V7-750-7F45',
    'LUM-PK-HEAD-MOTO-GUZZI-V7-RACER-750-77E4',
    'LUM-PK-HEAD-MOTO-GUZZI-V9-BOBBER-850-BE0C',
    'LUM-PK-HEAD-MOTO-GUZZI-V9-ROAMER-850-F113'
  ))
    AND p."name" LIKE 'Pack %'
)
UPDATE "Product" p
SET
  "name" = 'Boîtier de phare rond noir pour optique LED 7 pouces pour ' || c.vehicule,
  "tagline" = 'Pour le phare avant de votre ' || c.vehicule,
  "description" = 'Boîtier de phare rond noir pour optique LED 7 pouces pour ' || c.vehicule || '. ' || 'Le boîtier de phare rond noir satiné qui reçoit une optique LED de 7 pouces (optique non fournie).',
  "body" = replace('Le boîtier de phare rond, noir satiné, qui reçoit une optique LED de 7 pouces à la place du phare d’origine de votre {v}.', '{v}', vehicule) || E'\n\n' || replace('**L’optique LED n’est pas fournie** : ce boîtier est fait pour recevoir une optique ronde de 7 pouces, vendue à part.', '{v}', vehicule) || E'\n\n' || replace('## Dans le carton

- 1 boîtier de phare rond noir satiné, avec sa visserie', '{v}', vehicule) || E'\n\n' || replace('## Avant de commander

Vérifiez que vous avez, ou commandez, une optique LED ronde de 7 pouces. En cas de doute, écrivez-nous avec le modèle exact de votre {v}.', '{v}', vehicule) || E'\n',
  "metaTitle" = NULL,
  "metaDescription" = NULL,
  "status" = 'PUBLISHED',
  "publishedAt" = COALESCE(p."publishedAt", NOW()),
  "updatedAt" = NOW()
FROM cible c
WHERE p."id" = c."id" AND c.vehicule IS NOT NULL;

UPDATE "ProductVariant" v
SET "name" = p."name", "updatedAt" = NOW()
FROM "Product" p
WHERE v."productId" = p."id"
  AND p."id" IN (SELECT DISTINCT v."productId" FROM "ProductVariant" v WHERE v."sku" IN (
    'LUM-PK-HEAD-MOTO-GUZZI-AUDACE-1400-B2B7',
    'LUM-PK-HEAD-MOTO-GUZZI-BELLAGIO-940-9666',
    'LUM-PK-HEAD-MOTO-GUZZI-BREVA-1100-12-B6E4',
    'LUM-PK-HEAD-MOTO-GUZZI-BREVA-750-F9F3',
    'LUM-PK-HEAD-MOTO-GUZZI-CALIFORNIA-11-6C0B',
    'LUM-PK-HEAD-MOTO-GUZZI-CALIFORNIA-14-CB0F',
    'LUM-PK-HEAD-MOTO-GUZZI-GRISO-1100-3AE9',
    'LUM-PK-HEAD-MOTO-GUZZI-GRISO-1200-C95A',
    'LUM-PK-HEAD-MOTO-GUZZI-GRISO-850-15CF',
    'LUM-PK-HEAD-MOTO-GUZZI-V7-750-7F45',
    'LUM-PK-HEAD-MOTO-GUZZI-V7-RACER-750-77E4',
    'LUM-PK-HEAD-MOTO-GUZZI-V9-BOBBER-850-BE0C',
    'LUM-PK-HEAD-MOTO-GUZZI-V9-ROAMER-850-F113'
  ))
  AND p."name" LIKE 'Boîtier de phare rond noir pour optique LED 7 pouces pour %';

