UPDATE "Product" p
SET
  "name" = 'Centrale de clignotants LED pour ' || c.vehicule,
  "tagline" = 'Pour les clignotants de votre ' || c.vehicule,
  "description" = 'Centrale de clignotants LED pour ' || c.vehicule || '. ' || 'La centrale électronique qui remet les clignotants LED à la bonne cadence, sans résistance à ajouter.',
  "body" = replace('La centrale (le relais) qui commande les clignotants de votre {v}, prévue pour les clignotants LED.', '{v}', vehicule) || E'\n\n' || replace('Une LED consomme beaucoup moins qu’une ampoule : la centrale d’origine croit l’ampoule grillée et fait clignoter **deux fois plus vite**. Cette centrale remet la cadence normale, sans résistance à ajouter.', '{v}', vehicule) || E'\n\n' || replace('## Dans le carton

- 1 centrale de clignotants LED', '{v}', vehicule) || E'\n\n' || replace('## Avant de commander

Elle se branche à la place de la centrale d’origine. En cas de doute sur votre version, écrivez-nous avec le modèle exact de votre {v} : nous vérifions la prise.', '{v}', vehicule) || E'\n',
  "metaTitle" = NULL,
  "metaDescription" = NULL,
  "status" = 'PUBLISHED',
  "publishedAt" = COALESCE(p."publishedAt", NOW()),
  "updatedAt" = NOW()
FROM cible c
WHERE p."id" = c."id" AND c.vehicule IS NOT NULL;

