UPDATE "Product" p
SET
  "name" = 'Clignotants séquentiels LED pour ' || c.vehicule,
  "tagline" = 'Pour les clignotants de votre ' || c.vehicule,
  "description" = 'Clignotants séquentiels LED pour ' || c.vehicule || '. ' || 'Une paire de clignotants LED à défilement, avec les modules qui évitent le clignotement rapide.',
  "body" = replace('Une paire de clignotants LED à défilement pour votre {v}, à la place des clignotants d’origine.', '{v}', vehicule) || E'\n\n' || replace('La lumière orange défile de l’intérieur vers l’extérieur, comme sur les véhicules récents. **Les modules fournis évitent le clignotement trop rapide** si la moto avait des clignotants à ampoule.', '{v}', vehicule) || E'\n\n' || replace('## Dans le carton

- 2 clignotants LED séquentiels
- 2 modules anti-clignotement rapide', '{v}', vehicule) || E'\n\n' || replace('## Avant de commander

Une paire équipe un côté avant et un côté arrière, ou l’avant seul : pour changer les quatre clignotants, commandez-en deux. En cas de doute, écrivez-nous avec le modèle exact de votre {v}.', '{v}', vehicule) || E'\n',
  "metaTitle" = NULL,
  "metaDescription" = NULL,
  "status" = 'PUBLISHED',
  "publishedAt" = COALESCE(p."publishedAt", NOW()),
  "updatedAt" = NOW()
FROM cible c
WHERE p."id" = c."id" AND c.vehicule IS NOT NULL;

