SET
  "name" = 'Clignotants dynamiques LED de rétroviseurs pour ' || c.vehicule,
  "tagline" = 'Pour les rétroviseurs de votre ' || c.vehicule,
  "description" = 'Clignotants dynamiques LED de rétroviseurs pour ' || c.vehicule || '. ' || 'Une paire de clignotants LED à défilement pour les rétroviseurs, à la place de ceux d’origine.',
  "body" = replace('Une paire de clignotants LED à défilement pour les rétroviseurs de votre {v}, à la place de ceux d’origine.', '{v}', vehicule) || E'\n\n' || replace('La lumière orange défile vers l’extérieur, comme sur les modèles récents. Ils se clipsent dans le rétroviseur et se branchent sur la prise d’origine.', '{v}', vehicule) || E'\n\n' || replace('## Dans le carton

- 2 clignotants de rétroviseur LED, gauche et droit', '{v}', vehicule) || E'\n\n' || replace('## Avant de commander

Ce produit est prévu pour les rétroviseurs d’origine de votre {v}. En cas de doute sur votre version, écrivez-nous avec le modèle exact : nous vérifions.', '{v}', vehicule) || E'\n',
  "metaTitle" = NULL,
  "metaDescription" = NULL,
  "status" = 'PUBLISHED',
  "publishedAt" = COALESCE(p."publishedAt", NOW()),
  "updatedAt" = NOW()
FROM cible c
WHERE p."id" = c."id" AND c.vehicule IS NOT NULL;

UPDATE "ProductVariant" v
SET "name" = p."name", "updatedAt" = NOW()
FROM "Product" p
WHERE v."productId" = p."id"
  AND p."id" IN (SELECT DISTINCT v."productId" FROM "ProductVariant" v WHERE v."sku" IN (
    'LUM-PK-TURN-AUDI-A4-B9-C7C2',
    'LUM-PK-TURN-AUDI-A5-II-7347',
    'LUM-PK-TURN-AUDI-A8-D5-B721',
    'LUM-PK-TURN-AUDI-Q2-8C32',
    'LUM-PK-TURN-AUDI-Q7-II-7694',
    'LUM-PK-TURN-AUDI-R8-II-6462',
    'LUM-PK-TURN-BMW-X5-F15-F85-C4DF',
