-- repetiteurs : 20 fiches -----------------------------------------------------
WITH cible AS (
  SELECT p."id", substring(p."name" from ' pour (.+)$') AS vehicule
  FROM "Product" p
  WHERE p."id" IN (SELECT DISTINCT v."productId" FROM "ProductVariant" v WHERE v."sku" IN (
    'LUM-PK-TURN-AUDI-A4-B5-45B7',
    'LUM-PK-TURN-AUDI-A8-D2-D7BB',
    'LUM-PK-TURN-CITROEN-C5-II-04A1',
    'LUM-PK-TURN-CITROEN-ZX-00A5',
    'LUM-PK-TURN-MITSUBISHI-LANCER-EVOLUT-2F0F',
    'LUM-PK-TURN-OPEL-ASTRA-K-11F7',
    'LUM-PK-TURN-OPEL-CORSA-E-D639',
    'LUM-PK-TURN-OPEL-GRANDLAND-X-83AA',
    'LUM-PK-TURN-OPEL-INSIGNIA-B-0B61',
    'LUM-PK-TURN-PEUGEOT-206-1DCB',
    'LUM-PK-TURN-PEUGEOT-3008-6A09',
    'LUM-PK-TURN-PEUGEOT-406-E58B',
    'LUM-PK-TURN-PEUGEOT-5008-267C',
    'LUM-PK-TURN-PORSCHE-911-991-B7BF',
    'LUM-PK-TURN-PORSCHE-911-997-EC2B',
    'LUM-PK-TURN-PORSCHE-CAYENNE-II-958-C13C',
    'LUM-PK-TURN-PORSCHE-MACAN-248F',
    'LUM-PK-TURN-PORSCHE-PANAMERA-970-D24C',
    'LUM-PK-TURN-VOLKSWAGEN-POLO-3-6N1-6N-0219',
    'LUM-PK-TURN-VOLVO-S40-3B25'
  ))
    AND p."name" LIKE 'Pack %'
)
UPDATE "Product" p
SET
  "name" = 'Répétiteurs latéraux dynamiques LED pour ' || c.vehicule,
  "tagline" = 'Pour les ailes avant de votre ' || c.vehicule,
  "description" = 'Répétiteurs latéraux dynamiques LED pour ' || c.vehicule || '. ' || 'Une paire de répétiteurs latéraux LED à défilement, à la place de ceux des ailes avant.',
  "body" = replace('Une paire de répétiteurs latéraux LED à défilement pour votre {v}, à la place de ceux des ailes avant.', '{v}', vehicule) || E'\n\n' || replace('La lumière orange défile vers l’arrière, comme sur les modèles récents. Ils se clipsent à la place des répétiteurs d’origine et se branchent sur la prise d’origine.', '{v}', vehicule) || E'\n\n' || replace('## Dans le carton

- 2 répétiteurs latéraux LED, gauche et droit', '{v}', vehicule) || E'\n\n' || replace('## Avant de commander

Ce produit est prévu pour les ailes avant de votre {v}. En cas de doute sur votre version, écrivez-nous avec le modèle exact : nous vérifions.', '{v}', vehicule) || E'\n',
  "metaTitle" = NULL,
  "metaDescription" = NULL,
  "status" = 'PUBLISHED',
  "publishedAt" = COALESCE(p."publishedAt", NOW()),
  "updatedAt" = NOW()
FROM cible c
WHERE p."id" = c."id" AND c.vehicule IS NOT NULL;

